-- Quest objectives keep their display order apart from their save slot (StorageIndex), from TDB 7.3.5
ALTER TABLE `quest_objectives` ADD COLUMN `Order` TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `Type`;
CREATE TEMPORARY TABLE `qo_order` (`ID` INT UNSIGNED NOT NULL PRIMARY KEY, `Order` TINYINT UNSIGNED NOT NULL);
UPDATE `quest_objectives` qo JOIN `qo_order` o ON o.`ID` = qo.`ID` SET qo.`Order` = o.`Order`;
DROP TEMPORARY TABLE `qo_order`;
